#[test]
fn read_before_move_in_argument_order() {
    let source = "class Box { int value = 7; int get() { return value; } } void consume(Box box) {} Box identity(Box box) { return box; } boolean test(Box box) { return false; } void f(int n, Box x) { println(n); } void main() { Box a = new Box(); f(a.value, a); }";
    validate(source).unwrap_or_else(|e| panic!("{}", e.render("case.ncr", source)));
}
